from __future__ import annotations

from pathlib import Path, PurePosixPath, PureWindowsPath
import re
from typing import Any, Callable, Mapping, TypeVar, cast

import yaml
from yaml.constructor import ConstructorError

from kokoroarc.errors import KokoroError
from kokoroarc.packs.security import PackLimits, scan_pack
from kokoroarc.schemas import SchemaRegistry


_REFERENCE_SECTIONS = ("files", "locale_files", "scenario_files")
_REQUIRED_COMPONENTS = frozenset(
    {
        "identity",
        "evidence",
        "derived_profile",
        "overrides",
        "behavior",
        "growth",
        "expressions",
    }
)
_REQUIRED_LOCALES = frozenset({"zh-CN", "en-US", "ja-JP"})
_SCENARIO_NAME_PATTERN = re.compile(r"[a-z][a-z0-9]*(?:_[a-z0-9]+)*")
_Reference = TypeVar("_Reference")
_WINDOWS_ILLEGAL_CHARACTERS = frozenset('*?"<>|')
_WINDOWS_RESERVED_NAMES = frozenset(
    {
        "con",
        "prn",
        "aux",
        "nul",
        "conin$",
        "conout$",
        *(f"com{digit}" for digit in "123456789¹²³"),
        *(f"lpt{digit}" for digit in "123456789¹²³"),
    }
)


class _UniqueKeySafeLoader(yaml.SafeLoader):
    pass


def _construct_unique_mapping(
    loader: _UniqueKeySafeLoader, node: yaml.MappingNode, deep: bool = False
) -> dict[Any, Any]:
    mapping: dict[Any, Any] = {}
    for key_node, value_node in node.value:
        if key_node.tag == "tag:yaml.org,2002:merge":
            raise ConstructorError(
                None, None, "mapping merge keys are disabled", key_node.start_mark
            )
        key = loader.construct_object(key_node, deep=deep)
        try:
            duplicate = key in mapping
        except TypeError as error:
            raise ConstructorError(
                None, None, "mapping key is not hashable", key_node.start_mark
            ) from error
        if duplicate:
            raise ConstructorError(
                None, None, "duplicate mapping key", key_node.start_mark
            )
        mapping[key] = loader.construct_object(value_node, deep=deep)
    return mapping


_UniqueKeySafeLoader.add_constructor(
    yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG,
    _construct_unique_mapping,
)


def resolve_pack_file(root: Path, relative: str) -> Path:
    _validate_pack_reference(relative)

    try:
        resolved_root = root.resolve(strict=True)
        resolved = (resolved_root / relative).resolve(strict=False)
    except (OSError, RuntimeError, ValueError) as error:
        raise _unsafe_pack_path("reference could not be canonicalized") from error
    if not resolved.is_relative_to(resolved_root):
        raise _unsafe_pack_path("reference escapes the pack root")
    return resolved


def _validate_pack_reference(relative: str) -> None:
    if not isinstance(relative, str) or not relative:
        raise _unsafe_pack_path("reference must be a non-empty string")

    posix_path = PurePosixPath(relative)
    windows_path = PureWindowsPath(relative)
    if (
        "\\" in relative
        or ":" in relative
        or posix_path.is_absolute()
        or windows_path.drive
        or windows_path.root
        or ".." in posix_path.parts
        or any(_is_unsafe_windows_component(part) for part in posix_path.parts)
        or not relative.endswith((".yaml", ".yml"))
    ):
        raise _unsafe_pack_path("reference is not a pack-relative YAML path")


def _is_unsafe_windows_component(component: str) -> bool:
    if component.endswith((" ", ".")) or any(
        character in _WINDOWS_ILLEGAL_CHARACTERS or ord(character) < 32
        for character in component
    ):
        return True
    device_name = component.split(".", 1)[0].rstrip(" ").casefold()
    return device_name in _WINDOWS_RESERVED_NAMES


def load_yaml(path: Path) -> dict[str, Any]:
    try:
        contents = path.read_bytes()
    except OSError as error:
        raise _invalid_pack_data(
            "YAML file could not be read.", "read_failed"
        ) from error

    return parse_yaml_bytes(contents)


def parse_yaml_bytes(contents: bytes) -> dict[str, Any]:
    """Parse UTF-8 YAML bytes with the pack loader's data-only rules."""
    try:
        text = contents.decode("utf-8")
    except UnicodeError as error:
        raise _invalid_pack_data(
            "YAML file could not be read.", "read_failed"
        ) from error

    loader: _UniqueKeySafeLoader | None = None
    try:
        _reject_alias_events(text)
        loader = _UniqueKeySafeLoader(text)
        document = loader.get_single_data()
    # SafeLoader constructors can raise ordinary Python exceptions for hostile
    # implicit scalars (for example invalid timestamps or guarded huge ints).
    # Keep every data-originated parser failure inside the sanitized boundary.
    except Exception as error:
        raise _invalid_pack_data("YAML document is invalid.", "invalid_yaml") from error
    finally:
        if loader is not None:
            loader.dispose()

    if not isinstance(document, dict):
        raise _invalid_pack_data(
            "YAML document must contain a mapping.", "root_not_mapping"
        )
    return cast(dict[str, Any], document)


def _reject_alias_events(contents: str) -> None:
    events = yaml.parse(contents, Loader=yaml.SafeLoader)
    try:
        for event in events:
            if isinstance(event, yaml.events.AliasEvent):
                raise ConstructorError(
                    None, None, "YAML aliases are disabled", event.start_mark
                )
    finally:
        events.close()


def load_source_pack(root: Path, schemas: SchemaRegistry) -> dict[str, Any]:
    scanned_files = frozenset(scan_pack(root, PackLimits()))
    manifest_path = resolve_pack_file(root, "character.yaml")
    if manifest_path not in scanned_files:
        raise _invalid_pack_data(
            "Character pack reference was not found.", "unscanned_reference"
        )
from __future__ import annotations

import os
import stat
from dataclasses import dataclass
from pathlib import Path

from kokoroarc.errors import KokoroError


@dataclass(frozen=True, slots=True)
class PackLimits:
    max_files: int = 128
    max_file_bytes: int = 256_000
    max_total_bytes: int = 2_000_000
    max_depth: int = 6
    max_entries: int = 512


def scan_pack(root: Path, limits: PackLimits) -> list[Path]:
    """Perform a bounded, no-follow pre-scan of a character-pack directory."""
    _validate_limits(limits)
    resolved_root = _validate_root(root)

    files: list[Path] = []
    file_count = 0
    total_bytes = 0
    entry_count = 0
    directories = [resolved_root]

    while directories:
        directory = directories.pop()
        entries, observed_entries = _read_directory(
            directory, limits.max_entries - entry_count
        )
        entry_count += observed_entries
        child_directories: list[Path] = []

        for entry in entries:
            path = Path(entry.path)
            if _entry_is_symlink(entry):
                raise _unsafe_path(path, "symlink")
            if _path_is_junction(path):
                raise _unsafe_path(path, "junction")

            entry_stat = _entry_stat(entry, path)
            if _is_reparse_point(entry_stat):
                raise _unsafe_path(path, "reparse point")

            depth = len(path.relative_to(resolved_root).parts)
            if depth > limits.max_depth:
                raise _limit_exceeded("max_depth")

            resolved_path = _resolve_entry(path)
            if not resolved_path.is_relative_to(resolved_root):
                raise _unsafe_path(path, "outside pack root")

            if stat.S_ISDIR(entry_stat.st_mode):
                child_directories.append(resolved_path)
                continue
            if not stat.S_ISREG(entry_stat.st_mode):
                raise _unsafe_path(path, "unsupported entry type")
            if entry_stat.st_nlink != 1:
                raise _unsafe_path(path, "hardlinked file")

            size = entry_stat.st_size
            if size > limits.max_file_bytes:
                raise _limit_exceeded("max_file_bytes")

            file_count += 1
            if file_count > limits.max_files:
                raise _limit_exceeded("max_files")

            total_bytes += size
            if total_bytes > limits.max_total_bytes:
                raise _limit_exceeded("max_total_bytes")
            files.append(resolved_path)

        directories.extend(reversed(child_directories))

    return sorted(files, key=lambda path: path.as_posix())


def _validate_limits(limits: PackLimits) -> None:
    for field_name in (
        "max_files",
        "max_file_bytes",
        "max_total_bytes",
        "max_depth",
        "max_entries",
    ):
        value = getattr(limits, field_name)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise KokoroError(
                "PACK_LIMIT_INVALID",
                "Pack limits must be non-negative integers.",
                details={"field": field_name},
            )


def _validate_root(root: Path) -> Path:
    try:
        root_stat = root.lstat()
    except FileNotFoundError as exc:
        raise KokoroError(
            "PACK_NOT_FOUND",
            "Character pack root was not found.",
            details={"path": str(root)},
        ) from exc
    except OSError as exc:
        raise _scan_failed(root, exc) from exc

    if stat.S_ISLNK(root_stat.st_mode):
        raise _unsafe_path(root, "symlink root")
    if _path_is_junction(root) or _is_reparse_point(root_stat):
        raise _unsafe_path(root, "junction or reparse root")
    if not stat.S_ISDIR(root_stat.st_mode):
        raise _unsafe_path(root, "root is not a directory")

    try:
        return root.resolve(strict=True)
    except OSError as exc:
        raise _scan_failed(root, exc) from exc


def _read_directory(
    directory: Path, remaining_entries: int
) -> tuple[list[os.DirEntry[str]], int]:
    entries: list[os.DirEntry[str]] = []
    observed_entries = 0
    try:
        with os.scandir(directory) as iterator:
            for entry in iterator:
                observed_entries += 1
                if observed_entries > remaining_entries:
                    raise _limit_exceeded("max_entries")
                entries.append(entry)
    except OSError as exc:
        raise _scan_failed(directory, exc) from exc
    return sorted(entries, key=lambda entry: entry.name), observed_entries


def _entry_is_symlink(entry: os.DirEntry[str]) -> bool:
    try:
        return entry.is_symlink()
    except OSError as exc:
        raise _scan_failed(Path(entry.path), exc) from exc


